Author:     welpy-cw <h.w.forms@arcor.de>
AuthorDate: Thu Jul 10 11:39:02 2025 +0000
Commit:     welpy-cw <h.w.forms@arcor.de>
CommitDate: Thu Jul 10 11:39:02 2025 +0000

    Bug 1896280 - Limit maximal height of expanded attachment list in message browser. r=freaktechnik


    Fix the calculation of the preferred height of the attachment view and make it
    available to the style sheet, which uses it to determine the `max-height`
    property of the attachment view.

    Differential Revision: https://phabricator.services.mozilla.com/D254501

diff --git a/mail/base/content/msgHdrView.js b/mail/base/content/msgHdrView.js
index 0c76517fbf8..535dfaa51ec 100644
--- a/mail/base/content/msgHdrView.js
+++ b/mail/base/content/msgHdrView.js
@@ -2231,9 +2231,10 @@ function toggleAttachmentList(expanded, updateFocus) {
   }

   attachmentToggle.checked = expanded;
+  attachmentList.collapsed = !expanded;
+  attachmentView.classList.toggle("list-expanded", expanded);

   if (expanded) {
-    attachmentList.collapsed = false;
     if (!attachmentView.collapsed) {
       attachmentSplitter.collapsed = false;
     }
@@ -2244,25 +2245,25 @@ function toggleAttachmentList(expanded, updateFocus) {

     attachmentList.setOptimumWidth();

-    // By design, attachmentView should not take up more than 1/4 of the message
-    // pane space
-    attachmentView.style.height =
-      Math.min(
-        attachmentList.preferredHeight,
-        document.getElementById("messagepanebox").getBoundingClientRect()
-          .height / 4
-      ) + "px";
+    // Calculate the preferred height (the height that would allow us to fit
+    // everything without scrollbars) of the attachmentView. Add 2px to account
+    // for item's margin.
+    attachmentView.style.setProperty(
+      "--preferred-height",
+      attachmentList.scrollHeight + attachmentBar.scrollHeight + 2 + "px"
+    );

     if (updateFocus) {
       attachmentList.focus();
     }
   } else {
-    attachmentList.collapsed = true;
     attachmentSplitter.collapsed = true;
     attachmentBar.setAttribute(
       "tooltiptext",
       bundle.getString("expandAttachmentPaneTooltip")
     );
+
+    // This may have been set by the XUL splitter.
     attachmentView.style.height = null;

     if (updateFocus && document.activeElement == attachmentList) {
diff --git a/mail/base/content/widgets/mailWidgets.js b/mail/base/content/widgets/mailWidgets.js
index 6f8f62f4cb1..ab4ce8ef581 100644
--- a/mail/base/content/widgets/mailWidgets.js
+++ b/mail/base/content/widgets/mailWidgets.js
@@ -364,15 +364,6 @@
       return this._childNodes.length;
     }

-    /**
-     * Get the preferred height (the height that would allow us to fit
-     * everything without scrollbars) of the attachmentlist's bounding
-     * rectangle. Add 3px to account for item's margin.
-     */
-    get preferredHeight() {
-      return this.scrollHeight + this.getBoundingClientRect().height + 3;
-    }
-
     get _childNodes() {
       return this.querySelectorAll("richlistitem.attachmentItem");
     }
diff --git a/mail/themes/shared/mail/messageHeader.css b/mail/themes/shared/mail/messageHeader.css
index 8d7e643431c..dc6f59babd2 100644
--- a/mail/themes/shared/mail/messageHeader.css
+++ b/mail/themes/shared/mail/messageHeader.css
@@ -495,6 +495,13 @@ button.email-action-button {
   /* Allow the area to shrink. */
   min-width: 0;
   overflow: hidden;
+  flex: 0 1 auto;
+
+  &.list-expanded {
+    /* By design, attachmentView should not take up more than 1/4 of the message
+       pane space. */
+    max-height: min(var(--preferred-height), 25%);
+  }
 }

